<script setup lang="ts">
import {NCard,NCollapse,NCollapseItem} from 'naive-ui';
import type {ConfigMember} from '../../phase2';
import type {DirectoryAccessRule} from '../directory/types';
import {memberNames} from './capability-package-view';
defineProps<{members:ConfigMember[];webAccess?:{allowMemberIds:string[];denyMemberIds:string[];allowWorkspaceMembers?:boolean};directoryAccess?:{allowGroupMembers?:boolean;allow:DirectoryAccessRule[];deny:DirectoryAccessRule[]}}>();
function subject(rule:DirectoryAccessRule){try{const parts=JSON.parse(rule.subjectId);return `${rule.kind==='department'?'部门':'渠道用户'} · ${parts[3]??rule.subjectId}`;}catch{return `${rule.kind==='department'?'部门':'渠道用户'} · ${rule.subjectId}`;}}
</script>
<template><NCard class="employee-scope-summary" title="员工整体使用范围" size="small"><dl><div><dt>允许平台用户</dt><dd>{{ webAccess?.allowWorkspaceMembers?'工作区活跃成员（包括以后加入者）':memberNames(webAccess?.allowMemberIds??[],members).join('、')||'无' }}</dd></div><div><dt>渠道白名单</dt><dd> {{ directoryAccess?.allow.length??0 }} 项{{ !directoryAccess?.allow.length&&!directoryAccess?.allowGroupMembers?' · 未允许渠道使用者':'' }}</dd></div><div><dt>群内使用</dt><dd>{{ directoryAccess?.allowGroupMembers?'允许群成员在群内使用，私聊及网页仍按各自名单':'仅按已有渠道规则授权' }}</dd></div></dl><NCollapse v-if="directoryAccess?.allow.length||directoryAccess?.deny.length"><NCollapseItem title="查看渠道范围明细" name="directory"><div v-for="kind in (['allow'] as const)" :key="kind"><p v-for="rule in directoryAccess?.[kind]??[]" :key="JSON.stringify(rule)">{{ subject(rule) }}<template v-if="rule.kind==='department'"> · {{ rule.includeDescendants?'含子部门':'不含子部门' }}</template></p></div></NCollapseItem></NCollapse><p class="field-note">白名单渠道用户可在私聊和群聊使用；能力包不能扩大以上范围。平台账号与渠道身份分别授权。</p></NCard></template>
<style scoped>dl{display:grid;gap:0.75rem;margin:0}dl>div{display:grid;grid-template-columns:8.75rem minmax(0,1fr);gap:0.75rem}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}p{overflow-wrap:anywhere}@media(max-width:36.25rem){dl>div{grid-template-columns:1fr;gap:0.25rem}}</style>
